import subprocess, os, tempfile, shutil
def run_in(content, extra_args=[], formatter="default"):
    d = tempfile.mkdtemp()
    open(os.path.join(d,"main.go"),"w").write(content)
    # also create go.mod to avoid toolchain issues?
    r = subprocess.run(["/workspace/executable","-formatter",formatter]+extra_args+["./..."], cwd=d, capture_output=True, text=True)
    out=r.stdout; err=r.stderr; code=r.returncode
    shutil.rmtree(d)
    return out,err,code

