import subprocess, os, tempfile, shutil, json

def test_default(content, desc):
    d=tempfile.mkdtemp()
    open(os.path.join(d,"main.go"),"w").write(content)
    r=subprocess.run(["/workspace/executable","-formatter","json","./..."],cwd=d,capture_output=True,text=True)
    out=r.stdout
    shutil.rmtree(d)
    try:
        j=json.loads(out) if out.strip() not in ("","null") else []
    except: j="parse fail "+repr(out[:500])
    print(f"--- {desc} ---")
    if isinstance(j,list):
        for item in j:
            print(f"  {item['RuleName']}: {item['Failure'][:100]} (conf {item['Confidence']})")
        if not j: print("  (no failures)")
    else: print(j)

# Test various patterns that might be default rules
test_default('// Package main foo.
package main

import "fmt"

func main(){
 fmt.Println("hi")
}
', "use fmt?")

test_default('// Package main foo.
package main

func foo() int {
 if true {
 return 1
 }
 return 0
}
func main(){println(foo())}
', "if-return?")

