import subprocess, os, tempfile, shutil, json
def test(content, desc, cfg=None):
    d=tempfile.mkdtemp()
    open(os.path.join(d,"main.go"),"w").write(content)
    args=["/workspace/executable","-formatter","json"]
    if cfg:
        open(os.path.join(d,"c.toml"),"w").write(cfg)
        args+=["-config",os.path.join(d,"c.toml")]
    args+=["./..."]
    r=subprocess.run(args,cwd=d,capture_output=True,text=True)
    out=r.stdout
    shutil.rmtree(d)
    try:
        j=json.loads(out) if out.strip() not in ("","null") else []
    except: j="parse "+repr(out[:1000])
    print(f"--- {desc} cfg={repr(cfg)} ---")
    if isinstance(j,list):
        for item in j:
            print(f"  {item['RuleName']}: {item['Failure'][:120]}")
        if not j: print("  (no failures)")
    else: print(j)

# Test blank-imports with enableAll vs default - maybe blank-imports not default?
test('// Package main foo.
package main

import _ "fmt"
func main(){}
', "blank", None)
test('// Package main foo.
package main

import _ "fmt"
func main(){}
', "blank enableAll", 'enableAllRules=true
')
# if-return with enableAll?
test('// Package main foo.
package main

func foo(x int) int {
 if x==1 {
 return 1
 }
 return 0
}
func main(){println(foo(1))}
', "if-return default", None)
test('// Package main foo.
package main

func foo(x int) int {
 if x==1 {
 return 1
 }
 return 0
}
func main(){println(foo(1))}
', "if-return all", 'enableAllRules=true
')
# unreachable
test('// Package main foo.
package main

func foo() int {
 return 1
 println("hi")
}
func main(){println(foo())}
', "unreachable default", None)
test('// Package main foo.
package main

func foo() int {
 return 1
 println("hi")
}
func main(){println(foo())}
', "unreachable all", 'enableAllRules=true
')
# bare-return
test('// Package main foo.
package main

func foo() (x int) {
 x=1
 return
}
func main(){println(foo())}
', "bare default", None)
test('// Package main foo.
package main

func foo() (x int) {
 x=1
 return
}
func main(){println(foo())}
', "bare all", 'enableAllRules=true
')
# error-strings
test('// Package main foo.
package main

import "errors"
var e = errors.New("Foo")
func main(){println(e.Error())}
', "error-strings default", None)
test('// Package main foo.
package main

import "errors"
var e = errors.New("Foo")
func main(){println(e.Error())}
', "error-strings all", 'enableAllRules=true
')
