func knownRule(name string) bool {
	for _, r := range allRulesList() {
		if r == name {
			return true
		}
	}
	// also check defaults that might not be in all list
	for _, r := range defaultRulesList() {
		if r == name {
			return true
		}
	}
	return false
}

// TOML parsing

func loadConfig(path string, hasExplicit bool) (*Config, error) {
	cfg := defaultConfig()
	cfg.HasConfigFile = hasExplicit
	if !hasExplicit {
		// check default locations
		xdg := os.Getenv("XDG_CONFIG_HOME")
		home := os.Getenv("HOME")
		var candidates []string
		if xdg != "" {
			candidates = append(candidates, xdg+"/revive.toml")
		}
		if home != "" {
			candidates = append(candidates, home+"/revive.toml")
		}
		found := ""
		for _, c := range candidates {
			if _, err := os.Stat(c); err == nil {
				found = c
				break
			}
		}
		if found == "" {
			// use default rules
			for _, r := range defaultRulesList() {
				cfg.Rules[r] = &RuleConfig{}
			}
			return cfg, nil
		}
		path = found
		hasExplicit = true
		cfg.HasConfigFile = true
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("cannot read the config file")
	}
	return parseTOML(string(data), cfg)
}

func parseTOML(content string, cfg *Config) (*Config, error) {
	lines := strings.Split(content, "\n")
	// track defined keys for duplicate detection: map lower key -> line
	definedGlobal := map[string]int{}
	definedRuleKeys := map[string]map[string]int{} // rule -> key(lower) -> line
	currentRule := "" // "" means global
	// For rule prefix detection: [rule.xxx] case-insensitive prefix
	for idx, rawLine := range lines {
		lineno := idx + 1
		line := strings.TrimSpace(rawLine)
		// handle empty or comment
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// strip inline comment? TOML: # starts comment if preceded by space and not in string. Simplify: find # outside quotes
		lineNoComment := stripComment(line)
		lineNoComment = strings.TrimSpace(lineNoComment)
		if lineNoComment == "" {
			continue
		}
		// table header?
		if strings.HasPrefix(lineNoComment, "[") {
			// must end with ] possibly with trailing spaces? Already trimmed, but need to check
			// Find closing ]
			if !strings.Contains(lineNoComment, "]") {
				// check what error: e.g., "[rule.package-comments" -> expected '.' or ']' ... got '\n'
				// original: "toml: line 2: expected '.' or ']' to end table name, but got '\\n' instead"
				// For "[rule.package-comments" (missing ]), the error is line X: expected '.' or ']' ... got '\n'
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d: expected '.' or ']' to end table name, but got '\\n' instead", lineno)
			}
			// Check for extra after ]: e.g., "[rule.package-comments]]" -> error: expected top-level item to end with newline... got ']' instead
			// Find first ] position
			closeIdx := strings.Index(lineNoComment, "]")
			after := strings.TrimSpace(lineNoComment[closeIdx+1:])
			if after != "" && !strings.HasPrefix(after, "#") {
				// error: expected top-level item to end... but got X instead
				// For "]]", after is "]", so got ']' . For other, got first char?
				got := "'"
				if len(after) > 0 {
					c := after[0]
					if c == ']' {
						got = "']'"
					} else {
						got = fmt.Sprintf("'%c'", c)
					}
				}
				// need last key: "rule.package-comments" ?
				inner := strings.TrimSpace(lineNoComment[1:closeIdx])
				// last key is "rule.<inner without rule.?>"
				// For "[rule.package-comments]]", inner is "rule.package-comments", last key is that
				lastKey := inner
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): expected a top-level item to end with a newline, comment, or EOF, but got %s instead", lineno, lastKey, got)
			}
			inner := strings.TrimSpace(lineNoComment[1:closeIdx])
			if inner == "" {
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d: unexpected end of table name (table names cannot be empty)", lineno)
			}
			// Check for invalid table name like "[[[invalid" - contains '['?
			if strings.Contains(inner, "[") {
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d: expected '.' or ']' to end table name, but got '[' instead", lineno)
			}
			// inner should be like "rule.xxx" (case-insensitive rule)
			parts := strings.SplitN(inner, ".", 2)
			if len(parts) == 1 {
				// e.g., "[rule]"? What does original do? Unknown. Treat as global? But likely error or ignore. Let's ignore.
				currentRule = ""
				continue
			}
			prefix := parts[0]
			ruleName := parts[1]
			// prefix must be "rule" case-insensitive? If not, what? e.g., "[foo.bar]" - original probably ignores? Let's check: unknown table? For now, if prefix lower != "rule", ignore (set currentRule to "" and continue, but need to handle keys under it? They would be ignored? Simpler: set currentRule to special ignore)
			if !strings.EqualFold(prefix, "rule") {
				// Check if it's like "[rule.]" already handled? "[rule.]" inner is "rule." -> parts ["rule",""] -> ruleName empty -> error? Original for "[rule.]" gave "unexpected end of table name"? Let's see: we tested "[rule.]" ? Not yet. Our earlier test "[rule.]" not tested. Let's handle: if ruleName empty -> error unexpected end?
				// Actually "[rule.]" would have inner "rule." -> ruleName "" -> should error? Let's return same as empty table?
				if ruleName == "" {
					return nil, fmt.Errorf("cannot parse the config file: toml: line %d: unexpected end of table name (table names cannot be empty)", lineno)
				}
				currentRule = "__ignore__"
				continue
			}
			ruleName = strings.TrimSpace(ruleName)
			// ruleName may contain spaces? e.g., "[rule.package-comments ]" already trimmed? Inner trimmed, so ruleName includes? For "[rule.package-comments ]", inner is "rule.package-comments", no trailing. Good.
			// Check for empty ruleName
			if ruleName == "" {
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d: unexpected end of table name (table names cannot be empty)", lineno)
			}
			// Check for quotes? TOML allows quoted keys like "[rule.\"package-comments\"]"? Unlikely in tests. Ignore.
			// Validate rule exists later, but for now set currentRule
			// Duplicate table? If same rule defined twice? TOML would error? Let's handle: if rule already has defined keys and we see same table again, is it duplicate? In TOML, redefining table is allowed if not defined? Actually BurntSushi allows? For revive, duplicate [rule.X] might be allowed? Let's assume allowed (merge). But need to handle duplicate keys across same rule.
			if _, ok := cfg.Rules[ruleName]; !ok {
				cfg.Rules[ruleName] = &RuleConfig{}
				definedRuleKeys[ruleName] = map[string]int{}
			}
			// Check if rule prefix case? Already handled. Rule name case-sensitive, so keep as is.
			currentRule = ruleName
			continue
		}
		// key = value
		eqIdx := strings.Index(lineNoComment, "=")
		if eqIdx < 0 {
			// No '=', what error? e.g., 'severity = "warning" extra' -> expected top-level item to end... got 'e' instead
			// For line without '=', it's invalid. Return generic?
			// Find first non-space after? Simplify: return expected newline error with got first char of extra?
			// Actually 'severity = "warning" extra' has '=', but extra after value. That's handled below as extra check.
			// For line with no '=', like 'foobar' -> error: expected '='? Let's return similar to BurntSushi: "expected '=' to separate key from value, but got ..."?
			// We haven't probed that. For safety, return generic parse error.
			return nil, fmt.Errorf("cannot parse the config file: toml: line %d: expected '=' to separate key from value", lineno)
		}
		keyPart := strings.TrimSpace(lineNoComment[:eqIdx])
		valPart := strings.TrimSpace(lineNoComment[eqIdx+1:])
		// key may be quoted? Simplify: strip quotes if present
		key := strings.Trim(keyPart, "\"'")
		// key is case-sensitive for error message? Original preserves case in "last key" for global? For global, last key is key as written? e.g., 'Severity="error"' error message would use "Severity"? We didn't test type mismatch with caps for global? We tested 'Severity=123' ? Not yet. For duplicate, it used lower? Actually duplicate test with 'severity' twice gave last key "severity" (lower). For caps, need to check.
		// For now, preserve original key for messages, but use lower for lookup.
		keyLower := strings.ToLower(key)
		// value parsing: need to detect type and check extra after value
		val, valType, rest, err := parseValue(valPart, lineno)
		if err != nil {
			// parseValue already returns formatted error with line?
			// err is like "toml: line X ..."? Need to prefix "cannot parse the config file: "
			if strings.HasPrefix(err.Error(), "toml:") {
				return nil, fmt.Errorf("cannot parse the config file: %s", err.Error())
			}
			return nil, fmt.Errorf("cannot parse the config file: toml: line %d: %s", lineno, err.Error())
		}
		// check rest (extra after value) - should be empty or comment
		restTrim := strings.TrimSpace(rest)
		if restTrim != "" && !strings.HasPrefix(restTrim, "#") {
			// error: expected top-level item to end... got X instead
			// X is first char of restTrim
			gotChar := string(restTrim[0])
			// BurntSushi formats as got 'e' for "extra", got ']' for "]", etc. For string, it shows char with quotes?
			// For 'severity = "warning" extra', rest is 'extra', got 'e'
			var lastKey string
			if currentRule == "" || currentRule == "__ignore__" {
				lastKey = key
			} else {
				// need prefix as written? Original for rule keys uses "rule.<rule>.<key>" with original case? Let's preserve.
				// For "[rule.package-comments]]" case, lastKey was "rule.package-comments" (lower? Actually rule name lower? It was lower. For rule keys, e.g., duplicate test gave "rule.package-comments.severity" (all lower, even though key was lower). Need to check caps: if key is "Severity" caps, what is lastKey? Let's assume it preserves? But our earlier test with caps didn't trigger error, so unknown.
				lastKey = fmt.Sprintf("rule.%s.%s", currentRule, key)
			}
			return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): expected a top-level item to end with a newline, comment, or EOF, but got '%s' instead", lineno, lastKey, gotChar)
		}
		// Now assign based on currentRule
		if currentRule == "__ignore__" {
			continue
		}
		if currentRule == "" {
			// global
			if _, exists := definedGlobal[keyLower]; exists {
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): Key '%s' has already been defined.", lineno, key, key)
			}
			definedGlobal[keyLower] = lineno
			if err := assignGlobal(cfg, keyLower, key, val, valType, lineno); err != nil {
				return nil, err
			}
		} else {
			// rule
			if _, ok := definedRuleKeys[currentRule]; !ok {
				definedRuleKeys[currentRule] = map[string]int{}
			}
			if _, exists := definedRuleKeys[currentRule][keyLower]; exists {
				fullKey := fmt.Sprintf("rule.%s.%s", currentRule, key)
				return nil, fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): Key '%s' has already been defined.", lineno, fullKey, fullKey)
			}
			definedRuleKeys[currentRule][keyLower] = lineno
			if err := assignRule(cfg.Rules[currentRule], keyLower, key, val, valType, lineno, currentRule); err != nil {
				return nil, err
			}
		}
	}
	// After parsing, validate rules exist, handle enableAll/default, etc.
	// Check unknown rules
	for r := range cfg.Rules {
		if !knownRule(r) {
			return nil, fmt.Errorf("initializing revive - getting lint rules: cannot find rule: %s", r)
		}
	}
	// Handle enableAllRules, enableDefaultRules
	if cfg.EnableAllRules {
		for _, r := range allRulesList() {
			if _, ok := cfg.Rules[r]; !ok {
				cfg.Rules[r] = &RuleConfig{}
			}
		}
		// also need defaults that are not in all list? all list already includes most defaults, but add missing defaults
		for _, r := range defaultRulesList() {
			if _, ok := cfg.Rules[r]; !ok {
				cfg.Rules[r] = &RuleConfig{}
			}
		}
	} else if cfg.EnableDefaultRules {
		for _, r := range defaultRulesList() {
			if _, ok := cfg.Rules[r]; !ok {
				cfg.Rules[r] = &RuleConfig{}
			}
		}
	} else {
		// if no config file and no explicit rules? Actually loadConfig for no file already added defaults. For explicit file with no rules and no enable flags, Rules stays empty (no defaults). That's correct.
		// But what about explicit file with some rules and enableDefaultRules false (default)? Keep only explicit.
	}
	// Validate rule arguments? For line-length-limit, check arguments type
	for rName, rc := range cfg.Rules {
		if rName == "line-length-limit" {
			if len(rc.Arguments) > 0 {
				// first arg should be int
				switch v := rc.Arguments[0].(type) {
				case int64:
					_ = v
				case int:
					_ = v
				case float64:
					// float? Should be invalid? Original expects int. Float would be invalid? Let's treat as invalid.
					return nil, fmt.Errorf("initializing revive - getting lint rules: cannot configure rule: %q: invalid value passed as argument number to the %q rule", rName, rName)
				default:
					return nil, fmt.Errorf("initializing revive - getting lint rules: cannot configure rule: %q: invalid value passed as argument number to the %q rule", rName, rName)
				}
			}
		}
		// For other rules with arguments, generally ignore? But need to handle invalid types? For now, only line-length-limit validates.
		// What about other rules that take arguments like "add-constant" with allow list? They accept various types, so no validation.
	}
	return cfg, nil
}

func stripComment(line string) string {
	// find # outside quotes
	inStr := false
	var quote byte
	escaped := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if inStr {
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == quote {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				quote = c
			} else if c == '#' {
				return line[:i]
			}
		}
	}
	return line
}

func parseValue(s string, lineno int) (interface{}, string, string, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, "", "", fmt.Errorf("toml: line %d (last key %q): unexpected EOF; expected value", lineno, "")
		// Note: need last key? Caller will handle? For "severity = " case, original error is: "toml: line 1 (last key \"severity\"): unexpected EOF; expected value"
		// Our generic doesn't include key. Need to pass key. Simplify: return error with placeholder, caller will replace?
		// Instead, handle empty value specially in caller. For now, return generic.
	}
	// string
	if strings.HasPrefix(s, "\"") {
		// find closing "
		// handle escapes
		i := 1
		var sb strings.Builder
		escaped := false
		for ; i < len(s); i++ {
			c := s[i]
			if escaped {
				switch c {
				case 'n':
					sb.WriteByte('\n')
				case 't':
					sb.WriteByte('\t')
				case '"', '\\':
					sb.WriteByte(c)
				default:
					sb.WriteByte(c)
				}
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '"' {
				break
			} else {
				sb.WriteByte(c)
			}
		}
		if i >= len(s) {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated string", lineno)
		}
		rest := s[i+1:]
		return sb.String(), "string", rest, nil
	}
	if strings.HasPrefix(s, "'") {
		// literal string
		end := strings.Index(s[1:], "'")
		if end < 0 {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated string", lineno)
		}
		val := s[1 : 1+end]
		rest := s[1+end+1:]
		return val, "string", rest, nil
	}
	// array
	if strings.HasPrefix(s, "[") {
		// find matching ] handling nested? Simplify: find closing ] outside strings
		// For our purposes, arrays are simple like [80], ["a","b"], [123], etc.
		// Parse by scanning
		depth := 0
		inStr2 := false
		var q byte
		esc := false
		endIdx := -1
		for i := 0; i < len(s); i++ {
			c := s[i]
			if inStr2 {
				if esc {
					esc = false
				} else if c == '\\' {
					esc = true
				} else if c == q {
					inStr2 = false
				}
			} else {
				if c == '"' || c == '\'' {
					inStr2 = true
					q = c
				} else if c == '[' {
					depth++
				} else if c == ']' {
					depth--
					if depth == 0 {
						endIdx = i
						break
					}
				}
			}
		}
		if endIdx < 0 {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated array", lineno)
		}
		inner := s[1:endIdx]
		rest := s[endIdx+1:]
		// parse inner elements split by comma outside strings
		elems, elemTypes, err := parseArrayElements(inner, lineno)
		if err != nil {
			return nil, "", "", err
		}
		// check homogeneous? For error messages, need to detect incompatible like [123] for exclude (expects string) -> error mentions int64 vs string
		// Return slice and type "slice" ? But need element type for error? Actually error for exclude=[123] is: incompatible types: TOML value has type int64; destination has type string
		// That suggests it checks element type, not slice type. For our assign, we'll handle.
		_ = elemTypes
		return elems, "slice", rest, nil
	}
	// bool
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "true") {
		rest := s[4:]
		// ensure rest is delimiter (space, comma, ], #, newline, etc.)? For global bool, rest should be empty/comment. If s is "trueX", then it's invalid? But our rest check will catch.
		// Check that after "true", next char is not alnum/_?
		if len(s) > 4 {
			c := s[4]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
				// part of longer identifier? Then not bool. Fall through to error?
			} else {
				return true, "bool", rest, nil
			}
		} else {
			return true, "bool", rest, nil
		}
	}
	if strings.HasPrefix(lower, "false") {
		rest := s[5:]
		if len(s) > 5 {
			c := s[5]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			} else {
				return false, "bool", rest, nil
			}
		} else {
			return false, "bool", rest, nil
		}
	}
	// number? Try int then float
	// Find token end (space, comma, ], #, etc.)
	tokenEnd := len(s)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' || c == '\t' || c == ',' || c == ']' || c == '#' || c == '\n' {
			tokenEnd = i
			break
		}
	}
	token := s[:tokenEnd]
	rest := s[tokenEnd:]
	// try int
	if iv, err := strconv.ParseInt(token, 10, 64); err == nil {
		return iv, "int64", rest, nil
	}
	if fv, err := strconv.ParseFloat(token, 64); err == nil {
		return fv, "float", rest, nil
	}
	// datetime? ignore
	return nil, "", "", fmt.Errorf("toml: line %d: expected value but found %q instead", lineno, token)
}

func parseArrayElements(inner string, lineno int) ([]interface{}, []string, error) {
	inner = strings.TrimSpace(inner)
	if inner == "" {
		return []interface{}{}, []string{}, nil
	}
	var elems []interface{}
	var types []string
	// split by comma outside strings
	start := 0
	inStr := false
	var q byte
	esc := false
	for i := 0; i <= len(inner); i++ {
		var c byte
		if i < len(inner) {
			c = inner[i]
		} else {
			c = ','
		}
		if inStr {
			if esc {
				esc = false
			} else if c == '\\' {
				esc = true
			} else if c == q {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				q = c
			} else if c == ',' {
				part := strings.TrimSpace(inner[start:i])
				start = i + 1
				if part == "" {
					continue
				}
				v, t, rest, err := parseValue(part, lineno)
				if err != nil {
					return nil, nil, err
				}
				if strings.TrimSpace(rest) != "" {
					return nil, nil, fmt.Errorf("toml: line %d: extra data after value", lineno)
				}
				elems = append(elems, v)
				types = append(types, t)
			}
		}
	}
	return elems, types, nil
}

func assignGlobal(cfg *Config, keyLower, origKey string, val interface{}, valType string, lineno int) error {
	mkErr := func(exp string) error {
		// valType mapping: "string"->string, "bool"->bool, "int64"->int64, "float"->float, "slice"->slice
		// exp is like "float", "string", "integer", "boolean", "slice"
		// original messages use: string, float, integer, boolean, slice
		// valType "int64" maps to "int64" in message? e.g., severity=123 gave "int64" vs "string". Yes.
		// For int expected (errorCode), val string gives "string" vs "integer". Good.
		// For bool expected, val string gives "string" vs "boolean".
		// For slice expected, val string gives "string" vs "slice".
		// For float expected, val string gives "string" vs "float", val bool gives "bool" vs "float", val int? int is allowed for float (no error). So only string/bool error.
		var got string
		switch valType {
		case "string":
			got = "string"
		case "bool":
			got = "bool"
		case "int64":
			got = "int64"
		case "float":
			got = "float"
		case "slice":
			got = "slice"
		default:
			got = valType
		}
		return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type %s", lineno, origKey, got, exp)
	}
	switch keyLower {
	case "confidence":
		switch v := val.(type) {
		case float64:
			cfg.Confidence = v
		case int64:
			cfg.Confidence = float64(v)
		case int:
			cfg.Confidence = float64(v)
		default:
			// need to handle valType for message: if string -> string vs float, if bool -> bool vs float, if slice -> slice vs float? But original for confidence=true gave bool vs float. Good.
			return mkErr("float")
		}
	case "severity":
		if s, ok := val.(string); ok {
			cfg.Severity = s
		} else {
			return mkErr("string")
		}
	case "errorcode":
		switch v := val.(type) {
		case int64:
			cfg.ErrorCode = int(v)
		case int:
			cfg.ErrorCode = v
		case float64:
			// float for int? Original would error? Probably incompatible: float vs integer. Let's error.
			return mkErr("integer")
		default:
			return mkErr("integer")
		}
	case "warningcode":
		switch v := val.(type) {
		case int64:
			cfg.WarningCode = int(v)
		case int:
			cfg.WarningCode = v
		case float64:
			return mkErr("integer")
		default:
			return mkErr("integer")
		}
	case "exclude":
		if arr, ok := val.([]interface{}); ok {
			// check each element is string
			var strs []string
			for _, e := range arr {
				if s, ok := e.(string); ok {
					strs = append(strs, s)
				} else {
					// element type mismatch: original for exclude=[123] gave int64 vs string
					var got string
					switch e.(type) {
					case int64, int:
						got = "int64"
					case float64:
						got = "float"
					case bool:
						got = "bool"
					default:
						got = "string"
					}
					return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type string", lineno, origKey, got)
				}
			}
			cfg.Exclude = strs
		} else {
			return mkErr("slice")
		}
	case "ignoregeneratedheader":
		if b, ok := val.(bool); ok {
			cfg.IgnoreGeneratedHeader = b
		} else {
			return mkErr("boolean")
		}
	case "enableallrules":
		if b, ok := val.(bool); ok {
			cfg.EnableAllRules = b
		} else {
			return mkErr("boolean")
		}
	case "enabledefaultrules":
		if b, ok := val.(bool); ok {
			cfg.EnableDefaultRules = b
		} else {
			return mkErr("boolean")
		}
	default:
		// unknown global key: ignore
	}
	return nil
}

func assignRule(rc *RuleConfig, keyLower, origKey string, val interface{}, valType string, lineno int, ruleName string) error {
	mkErr := func(exp string) error {
		var got string
		switch valType {
		case "string":
			got = "string"
		case "bool":
			got = "bool"
		case "int64":
			got = "int64"
		case "float":
			got = "float"
		case "slice":
			got = "slice"
		default:
			got = valType
		}
		fullKey := fmt.Sprintf("rule.%s.%s", ruleName, origKey)
		return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type %s", lineno, fullKey, got, exp)
	}
	switch keyLower {
	case "arguments":
		if arr, ok := val.([]interface{}); ok {
			rc.Arguments = arr
		} else {
			return mkErr("slice")
		}
	case "severity":
		if s, ok := val.(string); ok {
			rc.Severity = s
		} else {
			return mkErr("string")
		}
	case "disabled":
		if b, ok := val.(bool); ok {
			rc.Disabled = b
		} else {
			return mkErr("boolean")
		}
	case "exclude":
		if arr, ok := val.([]interface{}); ok {
			var strs []string
			for _, e := range arr {
				if s, ok := e.(string); ok {
					strs = append(strs, s)
				} else {
					var got string
					switch e.(type) {
					case int64, int:
						got = "int64"
					case float64:
						got = "float"
					case bool:
						got = "bool"
					default:
						got = "string"
					}
					fullKey := fmt.Sprintf("rule.%s.%s", ruleName, origKey)
					return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type string", lineno, fullKey, got)
				}
			}
			rc.Exclude = strs
		} else {
			return mkErr("slice")
		}
	case "confidence":
		// ignored, any type allowed
	default:
		// unknown rule key: ignore
	}
	return nil
}
