func loadConfig(path string, hasExplicit bool) (*Config, error) {
	cfg := defaultConfig()
	cfg.HasConfigFile = hasExplicit
	if !hasExplicit {
		// check default locations
		xdg := os.Getenv("XDG_CONFIG_HOME")
		home := os.Getenv("HOME")
		var candidates []string
		if xdg != "" {
			candidates = append(candidates, xdg+"/revive.toml")
		}
		if home != "" {
			candidates = append(candidates, home+"/revive.toml")
		}
		found := ""
		for _, c := range candidates {
			if _, err := os.Stat(c); err == nil {
				found = c
				break
			}
		}
		if found == "" {
			// use default rules
			for _, r := range defaultRulesList() {
				cfg.Rules[r] = &RuleConfig{}
			}
			return cfg, nil
		}
		path = found
		hasExplicit = true
		cfg.HasConfigFile = true
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("cannot read the config file")
	}
	return parseTOML(string(data), cfg)
}

func parseTOML(content string, cfg *Config) (*Config, error) {
