func stripComment(line string) string {
	// find # outside quotes
	inStr := false
	var quote byte
	escaped := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if inStr {
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == quote {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				quote = c
			} else if c == '#' {
				return line[:i]
			}
		}
	}
	return line
}

func parseValue(s string, lineno int) (interface{}, string, string, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, "", "", fmt.Errorf("toml: line %d (last key %q): unexpected EOF; expected value", lineno, "")
		// Note: need last key? Caller will handle? For "severity = " case, original error is: "toml: line 1 (last key \"severity\"): unexpected EOF; expected value"
		// Our generic doesn't include key. Need to pass key. Simplify: return error with placeholder, caller will replace?
		// Instead, handle empty value specially in caller. For now, return generic.
	}
	// string
	if strings.HasPrefix(s, "\"") {
		// find closing "
		// handle escapes
		i := 1
		var sb strings.Builder
		escaped := false
		for ; i < len(s); i++ {
			c := s[i]
			if escaped {
				switch c {
				case 'n':
					sb.WriteByte('\n')
				case 't':
					sb.WriteByte('\t')
				case '"', '\\':
					sb.WriteByte(c)
				default:
					sb.WriteByte(c)
				}
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '"' {
				break
			} else {
				sb.WriteByte(c)
			}
		}
		if i >= len(s) {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated string", lineno)
		}
		rest := s[i+1:]
		return sb.String(), "string", rest, nil
	}
	if strings.HasPrefix(s, "'") {
		// literal string
		end := strings.Index(s[1:], "'")
		if end < 0 {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated string", lineno)
		}
		val := s[1 : 1+end]
		rest := s[1+end+1:]
		return val, "string", rest, nil
	}
	// array
	if strings.HasPrefix(s, "[") {
		// find matching ] handling nested? Simplify: find closing ] outside strings
		// For our purposes, arrays are simple like [80], ["a","b"], [123], etc.
		// Parse by scanning
		depth := 0
		inStr2 := false
		var q byte
		esc := false
		endIdx := -1
		for i := 0; i < len(s); i++ {
			c := s[i]
			if inStr2 {
				if esc {
					esc = false
				} else if c == '\\' {
					esc = true
				} else if c == q {
					inStr2 = false
				}
			} else {
				if c == '"' || c == '\'' {
					inStr2 = true
					q = c
				} else if c == '[' {
					depth++
				} else if c == ']' {
					depth--
					if depth == 0 {
						endIdx = i
						break
					}
				}
			}
		}
		if endIdx < 0 {
			return nil, "", "", fmt.Errorf("toml: line %d: unterminated array", lineno)
		}
		inner := s[1:endIdx]
		rest := s[endIdx+1:]
		// parse inner elements split by comma outside strings
		elems, elemTypes, err := parseArrayElements(inner, lineno)
		if err != nil {
			return nil, "", "", err
		}
		// check homogeneous? For error messages, need to detect incompatible like [123] for exclude (expects string) -> error mentions int64 vs string
		// Return slice and type "slice" ? But need element type for error? Actually error for exclude=[123] is: incompatible types: TOML value has type int64; destination has type string
		// That suggests it checks element type, not slice type. For our assign, we'll handle.
		_ = elemTypes
		return elems, "slice", rest, nil
	}
	// bool
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "true") {
		rest := s[4:]
		// ensure rest is delimiter (space, comma, ], #, newline, etc.)? For global bool, rest should be empty/comment. If s is "trueX", then it's invalid? But our rest check will catch.
		// Check that after "true", next char is not alnum/_?
		if len(s) > 4 {
			c := s[4]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
				// part of longer identifier? Then not bool. Fall through to error?
			} else {
				return true, "bool", rest, nil
			}
		} else {
			return true, "bool", rest, nil
		}
	}
	if strings.HasPrefix(lower, "false") {
		rest := s[5:]
		if len(s) > 5 {
			c := s[5]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			} else {
				return false, "bool", rest, nil
			}
		} else {
			return false, "bool", rest, nil
		}
	}
	// number? Try int then float
	// Find token end (space, comma, ], #, etc.)
	tokenEnd := len(s)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' || c == '\t' || c == ',' || c == ']' || c == '#' || c == '\n' {
			tokenEnd = i
			break
		}
	}
	token := s[:tokenEnd]
	rest := s[tokenEnd:]
	// try int
	if iv, err := strconv.ParseInt(token, 10, 64); err == nil {
		return iv, "int64", rest, nil
	}
	if fv, err := strconv.ParseFloat(token, 64); err == nil {
		return fv, "float", rest, nil
	}
	// datetime? ignore
	return nil, "", "", fmt.Errorf("toml: line %d: expected value but found %q instead", lineno, token)
}

func parseArrayElements(inner string, lineno int) ([]interface{}, []string, error) {
	inner = strings.TrimSpace(inner)
	if inner == "" {
		return []interface{}{}, []string{}, nil
	}
	var elems []interface{}
	var types []string
	// split by comma outside strings
	start := 0
	inStr := false
	var q byte
	esc := false
	for i := 0; i <= len(inner); i++ {
		var c byte
		if i < len(inner) {
			c = inner[i]
		} else {
			c = ','
		}
		if inStr {
			if esc {
				esc = false
			} else if c == '\\' {
				esc = true
			} else if c == q {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				q = c
			} else if c == ',' {
				part := strings.TrimSpace(inner[start:i])
				start = i + 1
				if part == "" {
					continue
				}
				v, t, rest, err := parseValue(part, lineno)
				if err != nil {
					return nil, nil, err
				}
				if strings.TrimSpace(rest) != "" {
					return nil, nil, fmt.Errorf("toml: line %d: extra data after value", lineno)
				}
				elems = append(elems, v)
				types = append(types, t)
			}
		}
	}
	return elems, types, nil
}

func assignGlobal(cfg *Config, keyLower, origKey string, val interface{}, valType string, lineno int) error {
	mkErr := func(exp string) error {
		// valType mapping: "string"->string, "bool"->bool, "int64"->int64, "float"->float, "slice"->slice
		// exp is like "float", "string", "integer", "boolean", "slice"
		// original messages use: string, float, integer, boolean, slice
		// valType "int64" maps to "int64" in message? e.g., severity=123 gave "int64" vs "string". Yes.
		// For int expected (errorCode), val string gives "string" vs "integer". Good.
		// For bool expected, val string gives "string" vs "boolean".
		// For slice expected, val string gives "string" vs "slice".
		// For float expected, val string gives "string" vs "float", val bool gives "bool" vs "float", val int? int is allowed for float (no error). So only string/bool error.
		var got string
		switch valType {
		case "string":
			got = "string"
		case "bool":
			got = "bool"
		case "int64":
			got = "int64"
		case "float":
			got = "float"
		case "slice":
			got = "slice"
		default:
			got = valType
		}
		return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type %s", lineno, origKey, got, exp)
	}
	switch keyLower {
	case "confidence":
		switch v := val.(type) {
		case float64:
			cfg.Confidence = v
		case int64:
			cfg.Confidence = float64(v)
		case int:
			cfg.Confidence = float64(v)
		default:
			// need to handle valType for message: if string -> string vs float, if bool -> bool vs float, if slice -> slice vs float? But original for confidence=true gave bool vs float. Good.
			return mkErr("float")
		}
	case "severity":
		if s, ok := val.(string); ok {
			cfg.Severity = s
		} else {
			return mkErr("string")
		}
	case "errorcode":
		switch v := val.(type) {
		case int64:
			cfg.ErrorCode = int(v)
		case int:
			cfg.ErrorCode = v
		case float64:
			// float for int? Original would error? Probably incompatible: float vs integer. Let's error.
			return mkErr("integer")
		default:
			return mkErr("integer")
		}
	case "warningcode":
		switch v := val.(type) {
		case int64:
			cfg.WarningCode = int(v)
		case int:
			cfg.WarningCode = v
		case float64:
			return mkErr("integer")
		default:
			return mkErr("integer")
		}
	case "exclude":
		if arr, ok := val.([]interface{}); ok {
			// check each element is string
			var strs []string
			for _, e := range arr {
				if s, ok := e.(string); ok {
					strs = append(strs, s)
				} else {
					// element type mismatch: original for exclude=[123] gave int64 vs string
					var got string
					switch e.(type) {
					case int64, int:
						got = "int64"
					case float64:
						got = "float"
					case bool:
						got = "bool"
					default:
						got = "string"
					}
					return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type string", lineno, origKey, got)
				}
			}
			cfg.Exclude = strs
		} else {
			return mkErr("slice")
		}
	case "ignoregeneratedheader":
		if b, ok := val.(bool); ok {
			cfg.IgnoreGeneratedHeader = b
		} else {
			return mkErr("boolean")
		}
	case "enableallrules":
		if b, ok := val.(bool); ok {
			cfg.EnableAllRules = b
		} else {
			return mkErr("boolean")
		}
	case "enabledefaultrules":
		if b, ok := val.(bool); ok {
			cfg.EnableDefaultRules = b
		} else {
			return mkErr("boolean")
		}
	default:
		// unknown global key: ignore
	}
	return nil
}

func assignRule(rc *RuleConfig, keyLower, origKey string, val interface{}, valType string, lineno int, ruleName string) error {
	mkErr := func(exp string) error {
		var got string
		switch valType {
		case "string":
			got = "string"
		case "bool":
			got = "bool"
		case "int64":
			got = "int64"
		case "float":
			got = "float"
		case "slice":
			got = "slice"
		default:
			got = valType
		}
		fullKey := fmt.Sprintf("rule.%s.%s", ruleName, origKey)
		return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type %s", lineno, fullKey, got, exp)
	}
	switch keyLower {
	case "arguments":
		if arr, ok := val.([]interface{}); ok {
			rc.Arguments = arr
		} else {
			return mkErr("slice")
		}
	case "severity":
		if s, ok := val.(string); ok {
			rc.Severity = s
		} else {
			return mkErr("string")
		}
	case "disabled":
		if b, ok := val.(bool); ok {
			rc.Disabled = b
		} else {
			return mkErr("boolean")
		}
	case "exclude":
		if arr, ok := val.([]interface{}); ok {
			var strs []string
			for _, e := range arr {
				if s, ok := e.(string); ok {
					strs = append(strs, s)
				} else {
					var got string
					switch e.(type) {
					case int64, int:
						got = "int64"
					case float64:
						got = "float"
					case bool:
						got = "bool"
					default:
						got = "string"
					}
					fullKey := fmt.Sprintf("rule.%s.%s", ruleName, origKey)
					return fmt.Errorf("cannot parse the config file: toml: line %d (last key %q): incompatible types: TOML value has type %s; destination has type string", lineno, fullKey, got)
				}
			}
			rc.Exclude = strs
		} else {
			return mkErr("slice")
		}
	case "confidence":
		// ignored, any type allowed
	default:
		// unknown rule key: ignore
	}
	return nil
}
