func stripComment(line string) string {
	// find # outside quotes
	inStr := false
	var quote byte
	escaped := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if inStr {
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == quote {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				quote = c
			} else if c == '#' {
				return line[:i]
			}
		}
	}
	return line
}

