	ast.Inspect(f, func(n ast.Node) bool {
		if block, ok := n.(*ast.BlockStmt); ok {
			for i, stmt := range block.List {
				// If stmt is return, break, continue, goto, and not last, then next stmts are unreachable
				isTerm := false
				switch stmt.(type) {
				case *ast.ReturnStmt, *ast.BranchStmt, *ast.GotoStmt:
					// BranchStmt includes break, continue, goto, fallthrough? Only break/continue/goto terminate? Fallthrough does not. Check.
					if br, ok := stmt.(*ast.BranchStmt); ok {
						if br.Tok == token.FALLTHROUGH {
