						}
					}
					isTerm = true
				}
				if isTerm && i+1 < len(block.List) {
					next := block.List[i+1]
					msg := "unreachable code after this statement"
					out = append(out, makeFailure("unreachable-code", "logic", msg, fset, next.Pos(), next.End(), filename, 1))
				}
			}
		}
		return true
	})
	return out
