// unexported-return
func ruleUnexportedReturn(fset *token.FileSet, f *ast.File, filename string) []Failure {
	var out []Failure
	pkgName := f.Name.Name
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if !ast.IsExported(fn.Name.Name) {
			continue
		}
		if fn.Type.Results == nil {
			continue
		}
		for _, field := range fn.Type.Results.List {
			// Check type is unexported (starts with lowercase) and in same package? e.g., returns "t" where type t is defined in same package (foo.t). Message includes package: "exported func Foo returns unexported type foo.t"
			// For our test: package foo, type t, func Foo() t -> message "exported func Foo returns unexported type foo.t"
			// How to get type name? For Ident "t", check if not exported and package is not main? Also need to ensure type is defined in same package? Simplify: if result type is Ident starting with lowercase, report.
			var typeName string
			var pos, end token.Pos
			switch t := field.Type.(type) {
			case *ast.Ident:
				typeName = t.Name
				pos = t.Pos()
				end = t.End()
			case *ast.StarExpr:
				if ident, ok := t.X.(*ast.Ident); ok {
					typeName = ident.Name
					pos = t.Pos()
					end = t.End()
				}
			default:
				continue
			}
			if typeName == "" || ast.IsExported(typeName) {
				continue
			}
			// Check if builtin? e.g., "int", "error", "string" are lowercase but not considered unexported? They are builtin, should not report. So skip builtins and common?
			if typeName == "int" || typeName == "string" || typeName == "error" || typeName == "bool" || typeName == "byte" || typeName == "rune" {
				continue
			}
			msg := fmt.Sprintf("exported func %s returns unexported type %s.%s, which can be annoying to use", fn.Name.Name, pkgName, typeName)
			out = append(out, makeFailure("unexported-return", "comments", msg, fset, pos, end, filename, 1))
		}
	}
	return out
}

