func writeFriendlyBreakdown(sb *strings.Builder, failures []Failure, severity string) {
	counts := map[string]int{}
	for _, f := range failures {
		if f.Severity == severity {
			counts[f.RuleName]++
		}
	}
	// Sort by count desc, then rule asc for determinism
	type kv struct {
		rule  string
		count int
	}
	var list []kv
	for k, v := range counts {
		list = append(list, kv{k, v})
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].count != list[j].count {
			return list[i].count > list[j].count
		}
		return list[i].rule < list[j].rule
	})
	for _, kv := range list {
		fmt.Fprintf(sb, "  %d  %s\n", kv.count, kv.rule)
	}
}

