func formatCheckstyle(failures []Failure) string {
	var sb strings.Builder
	sb.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n<checkstyle version=\"5.0\">\n")
	if len(failures) == 0 {
		sb.WriteString("</checkstyle>\n")
		return sb.String()
	}
	// Group by file
	filesMap := map[string][]Failure{}
	var order []string
	for _, f := range failures {
		fn := f.Position.Start.Filename
		if _, ok := filesMap[fn]; !ok {
			order = append(order, fn)
		}
		filesMap[fn] = append(filesMap[fn], f)
	}
	sort.Strings(order)
	for _, fn := range order {
		fmt.Fprintf(&sb, "    <file name=\"%s\">\n", escapeXML(fn))
		for _, f := range filesMap[fn] {
			// message is "failure (confidence X)" with XML escaping, severity, source="revive/rule"
			msg := fmt.Sprintf("%s (confidence %s)", f.Failure, formatConfidence(f.Confidence))
			fmt.Fprintf(&sb, "      <error line=\"%d\" column=\"%d\" message=\"%s\" severity=\"%s\" source=\"revive/%s\"/>\n", f.Position.Start.Line, f.Position.Start.Column, escapeXML(msg), f.Severity, escapeXML(f.RuleName))
		}
		sb.WriteString("    </file>\n")
	}
	sb.WriteString("</checkstyle>\n")
	return sb.String()
}

func formatConfidence(c float64) string {
	if c == 1 {
		return "1"
	}
	if c == 0.9 {
		return "0.9"
	}
	if c == 0.8 {
		return "0.8"
	}
	// Generic: trim?
	s := fmt.Sprintf("%g", c)
	return s
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

